-- Donnees de demonstration du tableau de bord (generees par generer-donnees-demo.py). Relancable.
START TRANSACTION;
DELETE ars FROM app_reservation_state ars JOIN occupation o ON o.code = ars.occupation_code WHERE o.observation = 'DEMO-MIRADOR';
DELETE FROM occupation WHERE observation = 'DEMO-MIRADOR';
DELETE FROM app_invoice_meta WHERE code_facture LIKE 'DMO-%';
DELETE FROM facture WHERE code_facture LIKE 'DMO-%';
DELETE FROM app_finance_transaction WHERE reference_code LIKE 'DEMO-%';
COMMIT;
